Mkt3L10n.adBridgeForm = {
  Back: "Zurück",
  Cancel: "Abbrechen",
  LinkedIn: "LinkedIn",
  Facebook: "Facebook",
  Google: "Google",
  MediaMath: "MediaMath",
  Turn: "Turn",
  Rocket_Fuel: "Rocket Fuel",
  LiveRamp: "LiveRamp",
  Send_to_Ad_Network: "An Ad Network senden",
  Next: "Weiter",
  Save: "Speichern",
  An_ad_type_must_be_selected: "Einen Ad Netzwerk-Typ auswählen",
  Ad_bridge_partner_ad_message_google: "Richten Sie Ihre Ausgaben für Google AdWords auf die richtigen potenziellen Kunden. Verbinden Sie Google AdWords Customer Match mit Marketo, um so leicht eine Google-Zielgruppe mit Hilfe von Leads aus einer statischen oder intelligente Liste von Marketo zu erstellen oder zu aktualisieren.<br/><br/><a href='{0}' target='_blank'>Weitere Informationen</a>",
  Ad_bridge_partner_ad_message_rocket_fuel: "Dank der Integration der Rocket Fuel Origin Platform in Marketo können Marketingteams einen beispiellosen ROI für Marketing und digitale Werbung erzielen und eine immer verfügbare Multi-Channel-Kundenerfahrung erreichen.<br/><br/><a href='http://launchpoint.marketo.com/rocket-fuel/1594-rocket-fuel-origin-platform' target='_blank'>Weitere Informationen</a>",
  Ad_bridge_partner_ad_message_turn: "Die Integration des Digital Hubs von Turn in Marketo versetzt Marketingteams in die Lage, die Conversion zu erhöhen und die Kosten für die Kundenakquise zu senken, da relevantere Zielgruppen über Anzeigen, mobile Kanäle, Video, soziale Netzwerke und TV erreicht werden.<br/><br/><a href='http://launchpoint.marketo.com/turn/1288-turn-dmp' target='_blank'>Weitere Informationen</a>",
  Ad_bridge_partner_ad_message_linkedin: "Sequenzieren Sie relevante Botschaften über Anzeigen und Werbung in sozialen Netzwerken, um den Fortschritt Ihrer Leads im Käuferzyklus zu beschleunigen.  Verbinden Sie Ihre Passende LinkedIn-Zielgruppen mit Marketo, und erstellen oder aktualisieren Sie einfach ein LinkedIn-Zielgruppensegment oder ersetzen es durch Leads aus einer statischen oder intelligenten Marketo-Liste.<br/><br/><a href='{0}' target='_blank'>Weitere Informationen</a>",
  Ad_bridge_partner_ad_message_linkedin_reauthorize: "Wir haben unserer LinkedIn-Matched-Audience-Verbindung in unserer Ausgabe Q1 2018 ein Upgrade gegeben. Bitte aktualisieren Sie Ihren Launchpoint Service für LinkedIn Matched Audience, um die neue Verbindung nutzen zu können.<br/><br/><a href='{0}' target='_blank'>Weitere Informationen</a>",
  Ad_bridge_partner_ad_message_linkedin_expired: "Marketo konnte sich nicht in Ihrem LinkedIn-Konto anmelden, da die Authentifizierung abgelaufen ist. Aktualisieren Sie die Zugangsdaten in LaunchPoint, und versuchen Sie es erneut.<br/><br/><a href='{0}' target='_blank'>Weitere Informationen</a>",
  Ad_bridge_partner_ad_message_facebook: "Richten Sie Ihre Ausgaben für Facebook-Werbung auf die richtigen potenziellen Kunden aus.  Verbinden Sie Ihr Facebook-Werbekonto mit Marketo und erstellen oder aktualisieren Sie einfach eine individuelle Facebook-Zielgruppe oder ersetzen sie durch Leads aus einer statischen oder intelligenten Marketo-Liste.<br/><br/><a href='{0}' target='_blank'>Weitere Informationen</a>",
  Ad_bridge_partner_ad_message_mediamath: "Durch die Kombination der leistungsstarken Funktionen von Marketo und dem TerminalOne Marketing Operating System™ von MediaMath können Marketingteams ihre Zielgruppen über alle Kanäle hinweg mit umfassenderem Kontext ansprechen.<br/><br/><a href='http://launchpoint.marketo.com/mediamath/1553-terminalone-marketing-operating-system' target='_blank'>Weitere Informationen</a>",
  Ad_bridge_partner_ad_message_liveramp: "Kombinieren Sie die Leistung von Marketo mit dem IdentityLink-Service von LiveRamp, um die Daten von Marketing-Initiativen überall in die digitalen Kanäle aufzunehmen. Wenden Sie sich für weitere Informationen an Ihren Kundenbetreuer oder melden Sie sich unten an.<br/><br/><a href='https://marketo.vertify.com' target='_blank'>Anmelden</a>"
};

