Mkt3L10n.socialAppDashboard = {
  Social_Dashboard: "Social Dashboard",
  Date_of_Activity: "Aktivitätsdatum",
  Last_Updated: "Zuletzt aktualisiert",
  Social_Funnel: "Social-Trichter",
  Audience: "Zielgruppe <span style='font-weight:normal'>(Gesamtprofile: {0})</span>",
  Share_Metrics: "Metriken freigeben",
  Share_Rate_percentage: "<div style=\"font-weight: bold\">Freigabequote:</div><p>Die Anzahl der Besuche, die eine Freigabe erzeugen.</p><br/><div style=\"font-weight: bold\">Clickback-Quote:</div> <p>Die Anzahl der Klicks, die aus einer Freigabe resultieren.</p><br/><div style=\"font-weight: bold\">Social Lift:</div><p>Das Verhältnis der Social Visits (von einer freigegebenen URL) zur Anzahl der Non-Social Visits (von anderen Quellen), in Prozent ausgedrückt.</p><br/>",
  Total_Profiles_number_users_who_signed_social_network: "<div style=\"font-weight: bold\">Gesamtprofile:</div><p>Die Anzahl der Benutzer, die sich über eine Social App bei einem sozialen Netzwerk angemeldet (bzw. mit diesem interagiert) haben.</p><br/> <div style=\"font-weight: bold\">Beeinflusser:</div><p>Die Anzahl der Benutzer, die mindestens einen empfohlenen Besuch aus einem freigegebenen Link erzeugt haben.</p><br/><div style=\"font-weight: bold\">Social Reach:</div><p>Die Gesamtsumme aller Benutzerverbindungen in einer Kampagne. Bei Benutzern von sozialen Netzwerken zählen wir die Anzahl der Freunde zum Zeitpunkt der Freigabe und bei E-Mail-Benutzern die Anzahl der Empfänger der von ihnen initiierten E-Mail.</p><br/><div style=\"font-weight: bold\">Social Impressions:</div><p>Die Häufigkeit, mit der von einer Kampagne freigegebene Nachrichten angesehen wurden. Dies wird durch Multiplikation des Social Reach jedes Sharers mit der Anzahl der Freigaben und der Addierung dieser Werte für alle Sharer berechnet.</p><br/>",
  Visits_number_sessions_Campaign: "<div style=\"font-weight: bold\">Besuche:</div><p>Die Häufigkeit, mit der Benutzer innerhalb eines bestimmten Zeitraums Ihre Seite aufgerufen haben(einzelne von den Besuchern initiierte Sitzungen). Benutzer, die eine Sitzung verlassen und innerhalb von 30 Minuten wieder zurückkehren, werden als zur Originalsitzung zugehörig gezählt. Unterbrechungen der Aktivität mit einer Dauer von mehr als 30 Minuten bzw. Schließen und Neustart des Browsers gelten als neue Sitzung bzw. als neuer Besuch.</p><br/><div style=\"font-weight: bold\">Kampagnenbesuche:</div><p>Die Anzahl der Besuche aller Kampagnen auf Ihrer Seite. Besuche einer Seite mit mehreren Platzierungen der gleichen Kampagne zählen als ein Kampagnenbesuch. Besuche mehrerer Seiten mit Platzierungen der gleichen Kampagne zählen ebenfalls als ein Kampagnenbesuch.</p><br/><div style=\"font-weight: bold\">Interaktionen:</div><p>Die Häufigkeit, mit der Benutzer eine soziale Aktion durchgeführt haben, z. B. Wählen, Bewerten, Freigeben, Posten eines Kommentars, Anmelden für ein Angebot, Freigeben eines Videos usw. </p><br/><div style=\"font-weight: bold\">Freigaben:</div><p>Die Häufigkeit, mit der Benutzer eine Nachricht an ein soziales Netzwerk freigegeben haben.</p><br/><div style=\"font-weight: bold\">Sich ergebende Klicks:</div><p>Die Anzahl der Seitenaufrufe, die durch freigegebene Links aus einer Kampagne erzeugt wurden.</p><br/><div style=\"font-weight: bold\">Konvertierungen:</div><p>Die Häufigkeit, mit der Benutzer eine bestimmte Aktion durchgeführt haben (wie das Kaufen eines Produkts), wie in einem auf Ihrer Seite implementierten Conversion Script definiert. \"Registrierungen\" (oder erstmalige Benutzer, deren Interaktion auf die Rückverfolgung eines freigegebenen Links auf Ihre Website zurückzuführen ist) sind das Standardkonvertierungsereignis, wenn kein Conversion Script bereitgestellt ist.</p><br/>",
  Data_will_be_updated_within_24_hours: "Die Daten werden innerhalb von 24 Stunden aktualisiert"
};

